<?php namespace App\Http\Controllers\Api\V1\Ai; use App\Http\Controllers\Controller; use App\Http\Requests\Ai\CreateConversationRequest; use App\Http\Resources\Ai\AiConversationResource; use App\Models\AiChatConversation; use App\Support\ApiResponse; use Illuminate\Support\Facades\Gate; class AiConversationController extends Controller { public function index() { $conversations = AiChatConversation::where("user_id", auth()->id())->where("is_archived", false)->latest()->paginate(15); return ApiResponse::success("Conversations retrieved successfully", AiConversationResource::collection($conversations)); } public function store(CreateConversationRequest $request) { $conversation = AiChatConversation::create([ "user_id" => auth()->id(), "title" => $request->validated("title") ?? "New Conversation", ]); return ApiResponse::success("Conversation created successfully", new AiConversationResource($conversation), 201); } public function show(AiChatConversation $conversation) { Gate::authorize("view", $conversation); $conversation->load(["messages" => function ($q) { $q->where("is_visible", true)->where("role", "!=", "system"); }]); return ApiResponse::success("Conversation retrieved successfully", new AiConversationResource($conversation)); } public function destroy(AiChatConversation $conversation) { Gate::authorize("delete", $conversation); $conversation->update(["is_archived" => true]); return ApiResponse::success("Conversation archived successfully"); } }